export function getLocaleCopy(locale) {
  const copy = COPIES[locale] || COPIES.ko;
  const keys = Object.keys(copy).sort();
  if (keys.join('|') !== REFERENCE_KEYS.join('|')) throw new TypeError(`Locale copy parity failed: ${locale}`);
  return Object.freeze({ ...copy });
}

export function getLocaleCopyKeys() {
  return REFERENCE_KEYS;
}
